import{_ as o,o as a,c,a3 as t}from"./chunks/framework.I6s8z2kk.js";const u=JSON.parse('{"title":"Reservations","description":"","frontmatter":{},"headers":[],"relativePath":"dev/domain/reservations.md","filePath":"dev/domain/reservations.md"}'),d={name:"dev/domain/reservations.md"};function n(s,e,r,i,l,h){return a(),c("div",null,[...e[0]||(e[0]=[t(`<h1 id="reservations" tabindex="-1">Reservations <a class="header-anchor" href="#reservations" aria-label="Permalink to &quot;Reservations&quot;">​</a></h1><p>The <strong>Reservations</strong> module books slots, enforces capacity and runs the reservation lifecycle, including packages and memberships.</p><h2 id="reservation-code" tabindex="-1">Reservation code <a class="header-anchor" href="#reservation-code" aria-label="Permalink to &quot;Reservation code&quot;">​</a></h2><p>Every reservation gets a unique public <code>code</code> on insert (<code>HasUniqueCode</code> in <code>modules/Support/src/Concerns</code>): 6 characters from <code>A-Z</code> and <code>2-9</code> without <code>I</code>, <code>L</code>, <code>O</code>, <code>0</code> and <code>1</code>, e.g. <code>K7QX2M</code>. It is never fillable; a unique index on <code>reservations.code</code> is the final guard. Lookups by code ignore case and surrounding spaces (<code>whereCode()</code>). The code is in every reservation resource.</p><h2 id="status-lifecycle" tabindex="-1">Status lifecycle <a class="header-anchor" href="#status-lifecycle" aria-label="Permalink to &quot;Status lifecycle&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pending ─► confirmed ─► completed</span></span>
<span class="line"><span>   │           ├────────► no_show</span></span>
<span class="line"><span>   └───────────┴────────► cancelled</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Rule</th><th>Detail</th></tr></thead><tbody><tr><td>Single entry point</td><td>Change status only through <code>ReservationStateService</code>. It locks the row, re-checks the status and fires its event after commit.</td></tr><tr><td><code>completed</code> / <code>no_show</code></td><td>Only from <code>confirmed</code>, and only after the slot started.</td></tr><tr><td>Reschedule</td><td>Only while <code>pending</code> or <code>confirmed</code>.</td></tr><tr><td>Capacity</td><td><code>pending</code>, <code>confirmed</code>, <code>completed</code> and <code>no_show</code> occupy capacity; <code>cancelled</code> does not. Use <code>Reservation::occupyingCapacity()</code>.</td></tr></tbody></table><h2 id="quoting-and-inserting" tabindex="-1">Quoting and inserting <a class="header-anchor" href="#quoting-and-inserting" aria-label="Permalink to &quot;Quoting and inserting&quot;">​</a></h2><p>Call <code>ReservationRules::quote()</code> inside a transaction that already holds <code>CapacityLock</code> (the service row, plus the trainer row when a trainer is set), and insert the reservation before commit. Overlap is half-open <code>[start, end)</code>. Capacity sums <code>quantity</code>; <code>null</code> capacity means unlimited.</p><h2 id="booking-violations" tabindex="-1">Booking violations <a class="header-anchor" href="#booking-violations" aria-label="Permalink to &quot;Booking violations&quot;">​</a></h2><p>Throw <code>ReservationNotAllowedException::because(&#39;&lt;key&gt;&#39;)</code>. It answers 422 with a <code>reason</code>, and the message comes from <code>reservations::booking.&lt;key&gt;</code>. <strong>Treat the keys as public API.</strong> Form Requests validate shape only; bookability is decided by the Booking rules classes.</p><h2 id="guards-for-every-service-type" tabindex="-1">Guards for every service type <a class="header-anchor" href="#guards-for-every-service-type" aria-label="Permalink to &quot;Guards for every service type&quot;">​</a></h2><ul><li><code>quantity &gt;= 1</code></li><li>The service is <code>ACTIVE</code></li><li>The client is not blocked by the center</li><li>No center-wide Resort <code>close_all_*</code> closure for the type</li><li>The single-session or package setting is on (only when the type declares it)</li><li>The slot is not in the past</li><li>No overlapping <code>ServiceBlock</code> (<code>service_id = null</code> means center-wide)</li></ul><h2 id="rules-per-type" tabindex="-1">Rules per type <a class="header-anchor" href="#rules-per-type" aria-label="Permalink to &quot;Rules per type&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>Rules</th></tr></thead><tbody><tr><td>Riding, Training</td><td>Needs a minute price option (a package option wins) and <code>start_time</code>. Slot = start + option minutes; it may end at 24:00 but not cross midnight and must fit one schedule window. Capacity is <code>max_tickets_per_hour</code>. Training uses the trainer&#39;s schedule and <code>maxTicketsPerHourOn(weekday)</code>, counted by <code>trainer_id</code> across all services. Package bookings are quantity 1 and price 0 for the same client and service.</td></tr><tr><td>Visit</td><td>No packages. The day must have a schedule; <code>specific_time</code> must equal a window start; <code>max_tickets_per_day</code> is shared across enter types.</td></tr><tr><td>Event</td><td>No packages. One ticket line. The date is within <code>start_date</code>–<code>end_date</code> and today is within <code>open_date</code>–<code>close_date</code>.</td></tr><tr><td>Resort</td><td>No packages. Quantity 1, inclusive date range, every day priced and unblocked. Any occupying overlap gives <code>resort_unavailable</code>. Add-ons once per stay.</td></tr><tr><td>Others</td><td>Not bookable.</td></tr></tbody></table><h2 id="cancellation" tabindex="-1">Cancellation <a class="header-anchor" href="#cancellation" aria-label="Permalink to &quot;Cancellation&quot;">​</a></h2><p>Only <strong>client</strong> cancellers are bound by <code>reservations.client_cancellation_cutoff_hours</code>. Cancelling:</p><ul><li>refunds <code>min(item total, refundable)</code> through the gateway for online payments, and <strong>aborts the cancel if the refund fails</strong></li><li>flags manual payments <code>refund_manual_required</code></li><li>gives no refund for cash or pending payments</li><li>restores one package credit</li></ul><h2 id="reschedule" tabindex="-1">Reschedule <a class="header-anchor" href="#reschedule" aria-label="Permalink to &quot;Reschedule&quot;">​</a></h2><p>Re-runs the full booking rules with <code>ignoreReservationId</code>, keeps the same service, and must not change the subtotal (<code>reschedule_price_changed</code>). A different price means cancel and rebook. The previous slot is appended to <code>metadata.reschedules</code>.</p><h2 id="packages-and-memberships" tabindex="-1">Packages and memberships <a class="header-anchor" href="#packages-and-memberships" aria-label="Permalink to &quot;Packages and memberships&quot;">​</a></h2><ul><li><code>BookFromPackage</code> locks the <code>ClientPackage</code>, enforces a trainer-bound package&#39;s trainer, creates the reservation <strong>Confirmed at price 0</strong>, and decrements <code>remaining_sessions</code> (0 means <code>exhausted</code>).</li><li>Membership visits need a usable membership before <code>expires_at</code> and a daily count (under lock) within <code>max_visits_per_day</code>. They are free and Confirmed.</li><li>Only <strong>sellable</strong> packages (active and not deleted) can be bought or quoted: <code>service_package_id</code> must exist with <code>status = active</code>. A membership whose included package is not sellable fails with <code>membership_package_unavailable</code>.</li><li>Packages and memberships are <strong>never sold as cash on arrival</strong>. They are created <code>pending</code> (membership packages at price 0) and activate on <code>PurchaseConfirmed</code>, with <code>expires_at</code> counted from activation (<code>servicePackage.duration</code> or the membership duration in months). Listeners are idempotent and only touch records still pending.</li><li><code>ClientPackage.knight_name</code> (nullable string, max 255) is set only by the owning client (<code>PATCH clients/packages/{package}</code>); <code>controlled</code> (bool, default false) is set only by center staff or admins (<code>PATCH centers/{center}/packages/{package}</code>, <code>reservations.manage</code>, paid packages of that center only). Both appear in every package resource.</li><li>Center staff manage a paid package of their center (same permission, also under <code>admin/centers/{center}/packages</code>): <code>POST packages/{package}/reservations</code> books a Confirmed price-0 session through <code>BookFromPackage</code> with source <code>center</code>; <code>POST packages/{package}/sessions</code> adds sessions (raises <code>total_sessions</code> and <code>remaining_sessions</code>, Exhausted goes back to Active, or stays Expired when the validity passed; cancelled packages are refused with <code>package_not_adjustable</code>); <code>PATCH packages/{package}</code> takes <code>controlled</code>, <code>trainer_id</code> and <code>expires_at</code> (at least one). The trainer must belong to the center and teach the package&#39;s training service (<code>invalid_trainer</code>; other service types <code>package_not_trainer_bound</code>; null frees it). A new expiry must be in the future and later than the current one (<code>invalid_expiry</code>); it resets <code>expiry_reminder_sent_at</code> and turns an Expired package with sessions left back to Active.</li></ul><h2 id="checkout" tabindex="-1">Checkout <a class="header-anchor" href="#checkout" aria-label="Permalink to &quot;Checkout&quot;">​</a></h2><p>Checkout accepts only <code>pending</code>, non-package reservations with total &gt; 0, of <strong>one client and one center</strong>, without an existing purchase item.</p><ul><li>Cash on arrival needs <code>enable_cash_on_arrival</code> on every service and confirms immediately.</li><li>Online payment leaves the reservations <code>pending</code>.</li><li>A total ≤ 0 confirms with no purchase.</li><li>Booking and checkout share one transaction.</li></ul><h2 id="unpaid-holds" tabindex="-1">Unpaid holds <a class="header-anchor" href="#unpaid-holds" aria-label="Permalink to &quot;Unpaid holds&quot;">​</a></h2><p><code>reservations:release-unpaid</code> cancels pending online purchases older than <code>unpaid_hold_minutes</code>, but only if, re-checked under lock, they have no <code>processing</code>, <code>succeeded</code> or <code>refunded</code> payment. Pending payments stay open. A payment that succeeds on an already-cancelled purchase is <strong>refunded automatically</strong>.</p><h2 id="purchase-summary-on-resources" tabindex="-1">Purchase summary on resources <a class="header-anchor" href="#purchase-summary-on-resources" aria-label="Permalink to &quot;Purchase summary on resources&quot;">​</a></h2><p><code>ReservationResource</code>, <code>ClientPackageResource</code>, <code>ClientMembershipResource</code> and their center variants embed <code>purchase</code> (<code>PurchaseSummaryResource</code>): <code>id</code>, <code>code</code>, <code>status</code>, <code>channel</code>, <code>total_amount</code>, <code>discount_amount</code>, <code>coupon_code</code>, <code>payment_method</code>, <code>payment_status</code>, <code>created_at</code>, plus <code>client</code> (<code>id</code>, <code>full_name</code>, <code>phone_number</code>) and <code>center</code> (<code>id</code>, <code>name</code>, <code>city</code>, <code>address</code>, <code>lat</code>, <code>lng</code>, <code>contact_phone</code>). It comes from the record&#39;s latest <code>purchaseItem</code> and is <code>null</code> when the record was not sold through a purchase (a session drawn from a package or membership, packages included in a membership). It is only present when the controller loads <code>PurchaseSummaryResource::RELATIONS</code>, so nested resources (a membership&#39;s <code>packages</code>) omit it.</p><h2 id="client-endpoints" tabindex="-1">Client endpoints <a class="header-anchor" href="#client-endpoints" aria-label="Permalink to &quot;Client endpoints&quot;">​</a></h2><p><code>reservations</code> (list, show, show by <code>code/{code}</code>, create, <code>quote</code>, <code>cancel</code>), <code>purchases/code/{code}</code> (one of the client&#39;s purchases, <code>ClientPurchaseResource</code>), <code>bookings</code>, <code>packages</code> and <code>memberships</code> (list, <code>quote</code>, buy), <code>PATCH packages/{package}</code> (set <code>knight_name</code>), <code>packages/{package}/reservations</code>, <code>memberships/{membership}/visits</code>.</p><h2 id="center-endpoints" tabindex="-1">Center endpoints <a class="header-anchor" href="#center-endpoints" aria-label="Permalink to &quot;Center endpoints&quot;">​</a></h2><p><code>centers/{center}/reservations</code> (and the same under <code>admin/centers/{center}/reservations</code>): list, <code>calendar</code>, show, show by <code>code/{code}</code> (404 for another center&#39;s code), create, <code>quote</code>, <code>reschedule</code>, <code>cancel</code>, <code>complete</code>, <code>no-show</code>.</p>`,33)])])}const m=o(d,[["render",n]]);export{u as __pageData,m as default};
